// Confirm: a dense accent slab after the form — one solid inverse band, heavy display
// headline on the left, short text with links on the right; slab layout, unlike the sections above.
type Link = { label: string; href: string };

export type BookingConfirmProps = {
  headline: string;
  text: string;
  links: Link[];
};

import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { safeHref } from "@wizard/ui-kit/v3/headless";

const linkClass =
  "inline-flex min-h-11 items-center justify-center rounded-control border-2 border-scrim-foreground/40 px-6 text-center text-body font-bold text-scrim-foreground transition-colors duration-200 hover:border-scrim-foreground hover:bg-scrim-foreground/10 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-scrim-foreground";

export default function BookingConfirm({ headline, text, links }: BookingConfirmProps) {
  const reduced = useReducedMotion();
  return (
    <section className="bg-scrim font-sans text-scrim-foreground">
      <LazyMotion features={domAnimation}>
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.div
            initial={reduced ? false : { opacity: 0, y: 24 }}
            whileInView={reduced ? undefined : { opacity: 1, y: 0 }}
            viewport={{ once: true, amount: 0.3 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="grid items-end gap-x-12 gap-y-8 lg:grid-cols-12"
          >
            <h2 className="min-w-0 font-display text-h1 font-bold text-balance wrap-break-word lg:col-span-7">
              {headline}
            </h2>
            <div className="min-w-0 lg:col-span-5">
              <p className="max-w-text text-lead text-pretty text-scrim-foreground/80">{text}</p>
              {links && links.length > 0 ? (
                <div className="mt-6 flex flex-col gap-3 sm:flex-row sm:flex-wrap">
                  {links.map((l) => (
                    <a key={l.href} href={safeHref(l.href)} className={linkClass}>
                      {l.label}
                    </a>
                  ))}
                </div>
              ) : null}
            </div>
          </m.div>
        </div>
      </LazyMotion>
    </section>
  );
}

