// Steps «horizontal chain»: airy section — headline above, three steps in a horizontal row
// joined by a continuous baseline rule; the step number is drawn by the code as a circular
// badge in primary, the rule passes behind it. Rise entrance, calm.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = { title: string; text: string };

export type BookingStepsProps = {
  headline: string;
  steps: Step[];
};

export default function BookingSteps({ headline, steps }: BookingStepsProps) {
  const still = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <m.h2
          className="max-w-text font-display text-h1 font-bold text-balance wrap-break-word"
          initial={still ? false : { opacity: 0, y: 24 }}
          whileInView={still ? undefined : { opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.6, ease: "easeOut" }}
        >
          {headline}
        </m.h2>

        <ol className="relative mt-16 grid gap-12 sm:grid-cols-3 sm:gap-8">
          {/* соединяющая линия: проходит за номерами шагов */}
          <span
            aria-hidden="true"
            className="absolute top-6 left-0 hidden h-px w-full bg-border sm:block"
          />
          {steps.map((step, i) => (
            <m.li
              key={step.title}
              className="relative min-w-0"
              initial={still ? false : { opacity: 0, y: 24 }}
              whileInView={still ? undefined : { opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-80px" }}
              transition={{ duration: 0.55, ease: "easeOut", delay: still ? 0 : i * 0.12 }}
            >
              <span
                aria-hidden="true"
                className="relative z-10 flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-primary font-display text-h3 font-bold text-primary-foreground"
              >
                {i + 1}
              </span>
              <div className="mt-6 pl-0 sm:pl-2">
                <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                <p className="mt-3 max-w-text text-body text-pretty text-muted-foreground">{step.text}</p>
              </div>
            </m.li>
          ))}
        </ol>
      </div>
    </section>
  );
}

