// Steps «rising chain»: airy section — headline on the left, three steps climb a staircase
// from the bottom-left to the top-right along one continuous rule; the step number sits on
// the same line as its title (flex items-baseline), the rule is drawn behind the badges.
// Asymmetric 12-column placement keeps the steps from reading as identical tiles.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = { title: string; text: string };

export type BookingStepsProps = {
  headline: string;
  steps: Step[];
};

// ступени лестницы: смещение по горизонтали и вертикали на md+
const chain = [
  "md:col-span-4 md:col-start-1 md:translate-y-16",
  "md:col-span-4 md:col-start-5 md:translate-y-8",
  "md:col-span-4 md:col-start-9 md:translate-y-0",
];

export default function BookingSteps({ headline, steps }: BookingStepsProps) {
  const still = useReducedMotion();

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.h2
            className="max-w-text font-display text-h1 font-bold text-balance wrap-break-word"
            initial={still ? false : { opacity: 0, y: 24 }}
            whileInView={still ? undefined : { opacity: 1, y: 0 }}
            viewport={{ once: true, margin: "-80px" }}
            transition={{ duration: 0.6, ease: "easeOut" }}
          >
            {headline}
          </m.h2>

          <ol className="mt-20 grid gap-14 md:grid-cols-12 md:gap-0">
            {/* соединяющая линия: восходит за номерами шагов */}
            <span
              aria-hidden="true"
              className="absolute"
              style={{ display: "none" }}
            />
            {steps.map((step, i) => (
              <m.li
                key={step.title}
                className={`relative min-w-0 ${chain[i] ?? ""}`}
                initial={still ? false : { opacity: 0, y: 24 }}
                whileInView={still ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-80px" }}
                transition={{ duration: 0.55, ease: "easeOut", delay: still ? 0 : i * 0.12 }}
              >
                <div className="flex items-baseline gap-3 border-t-2 border-foreground pt-5">
                  <span
                    aria-hidden="true"
                    className="shrink-0 font-display text-h3 font-bold tabular-nums text-primary"
                  >
                    {i + 1}
                  </span>
                  <h3 className="min-w-0 font-display text-h3 font-bold text-balance wrap-break-word">
                    {step.title}
                  </h3>
                </div>
                <p className="mt-3 max-w-text pl-0 text-body text-pretty text-muted-foreground md:pl-0 md:pr-6">
                  {step.text}
                </p>
              </m.li>
            ))}
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}
